// Validate booking details, amount, and customer auth
const body = $input.item.json.body;
if (!body.amount || !body.booking_id || !body.customer_id) {
  throw new Error('Invalid request payload');
}

// Convert INR amount to paise
const amountInPaise = Math.round(Number(body.amount) * 100);

return {
  amount: amountInPaise,
  currency: 'INR',
  receipt: `rcpt_${body.booking_id.substring(0, 15)}`,
  notes: {
    booking_id: body.booking_id,
    customer_id: body.customer_id,
    service_name: body.service_name || 'Zolve Service'
  }
};
